/**
 * GET /api/auth/google/start
 *
 * The single entry point for "Sign in with Google" and "Sign up with Google".
 *
 * The desktop app opens this URL in the system browser, so the flow always
 * starts on the StackPilot site (`http://localhost:3000`) instead of jumping
 * straight to accounts.google.com. Google then redirects back to
 * `/auth/callback`, which hands the finished session to the desktop listener.
 *
 * Query:
 *   state   - opaque value generated by the desktop; Google echoes it back so
 *             the desktop can verify the round-trip. Optional - minted here when
 *             the flow is started from the site itself.
 *   intent  - "signin" (default) or "signup"; both run the same OAuth flow, the
 *             backend creates the account when the Google email is new.
 *
 * Response: 302 → Google consent screen, 500 when OAuth is not configured.
 */
import { NextRequest, NextResponse } from "next/server";

const GOOGLE_AUTH_ENDPOINT = "https://accounts.google.com/o/oauth2/v2/auth";

export async function GET(request: NextRequest) {
  const clientId = process.env.GOOGLE_CLIENT_ID;
  if (!clientId) {
    console.error("[google-start] GOOGLE_CLIENT_ID is not configured");
    return Response.json(
      { error: "Google sign-in is not configured on the site." },
      { status: 500 }
    );
  }

  const url = new URL(request.url);
  // Must match the authorized redirect URI in Google Console, so prefer the
  // configured site URL over whatever host this request arrived on.
  const siteUrl = (process.env.NEXT_PUBLIC_SITE_URL ?? url.origin).replace(/\/+$/, "");
  const intent = url.searchParams.get("intent") === "signup" ? "signup" : "signin";
  const state = url.searchParams.get("state")?.trim() || crypto.randomUUID();

  const authUrl = new URL(GOOGLE_AUTH_ENDPOINT);
  authUrl.searchParams.set("client_id", clientId);
  authUrl.searchParams.set("redirect_uri", `${siteUrl}/auth/callback`);
  authUrl.searchParams.set("response_type", "code");
  authUrl.searchParams.set("scope", "openid email profile");
  authUrl.searchParams.set("state", state);
  authUrl.searchParams.set("access_type", "offline");
  authUrl.searchParams.set("prompt", "select_account");

  console.log(`[google-start] ${intent} → ${siteUrl}/auth/callback`);

  // Never cache: every click needs a fresh consent redirect and its own state.
  return NextResponse.redirect(authUrl.toString(), {
    status: 302,
    headers: { "Cache-Control": "no-store, max-age=0" },
  });
}
